import json

# Read current flow
with open('/work/output/artifacts/skill-flow-devcon-billing-invoice-lookup/BillingInvoiceLookup/BillingInvoiceLookup/BillingInvoiceLookup.flow') as f:
    flow = json.load(f)

# Read script def
with open('/tmp/def_script.json') as f:
    sd = json.load(f)
with open('/tmp/def_end.json') as f:
    ed = json.load(f)

script_def = sd.get('Node', sd)
end_def = ed.get('Node', ed)

# --- BUILD THE NEW FLOW ---

flow['nodes'] = [
    # Manual trigger with invoiceNumber input
    {
        "id": "start",
        "type": "core.trigger.manual",
        "typeVersion": "1.0",
        "display": {"label": "Manual trigger"},
        "inputs": {
            "entryPointId": flow['nodes'][0]['inputs']['entryPointId'],
            "isDefaultEntryPoint": True
        },
        "outputs": {
            "output": {
                "type": "object",
                "description": "The return value of the trigger.",
                "source": "=result.response",
                "var": "output"
            }
        }
    },
    # Normalize the invoice number
    {
        "id": "normalizeInvoice",
        "type": "core.action.script",
        "typeVersion": "1.0",
        "display": {"label": "Normalize Invoice Number"},
        "inputs": {
            "script": (
                "var raw = $vars.start.output.invoiceNumber;\n"
                "if (raw === undefined || raw === null) { raw = ''; }\n"
                "var trimmed = String(raw).trim().toUpperCase();\n"
                "var normalized = trimmed.startsWith('MCS-') ? trimmed : 'MCS-' + trimmed;\n"
                "return { normalizedInvoiceNumber: normalized };"
            )
        },
        "outputs": {
            "output": {
                "type": "object",
                "description": "The return value of the script",
                "source": "=result.response",
                "var": "output"
            },
            "error": {
                "type": "object",
                "description": "Error information if the script fails",
                "source": "=result.Error",
                "var": "error"
            }
        }
    },
    # Connector: Query BillingDisputeERP (existing node added via CLI)
    {
        "id": "queryBillingdisputeerp1",
        "type": "uipath.connector.uipath-uipath-dataservice.query-entity-records",
        "typeVersion": "1.0.0",
        "display": {"label": "Query BillingDisputeERP"},
        "inputs": {}
    },
    # Build outputs script
    {
        "id": "buildOutputs",
        "type": "core.action.script",
        "typeVersion": "1.0",
        "display": {"label": "Build Outputs"},
        "inputs": {
            "script": (
                "var records = $vars.queryBillingdisputeerp1.output;\n"
                "var rows = [];\n"
                "if (Array.isArray(records)) {\n"
                "  rows = records;\n"
                "} else if (records && Array.isArray(records.value)) {\n"
                "  rows = records.value;\n"
                "} else if (records && Array.isArray(records.Value)) {\n"
                "  rows = records.Value;\n"
                "}\n"
                "var matchedInvoiceNumber = rows.length > 0 ? rows[0].invoiceNumber : $vars.normalizeInvoice.output.normalizedInvoiceNumber;\n"
                "var lineItemCount = rows.length;\n"
                "return { matchedInvoiceNumber: matchedInvoiceNumber, lineItemCount: lineItemCount };"
            )
        },
        "outputs": {
            "output": {
                "type": "object",
                "description": "The return value of the script",
                "source": "=result.response",
                "var": "output"
            },
            "error": {
                "type": "object",
                "description": "Error information if the script fails",
                "source": "=result.Error",
                "var": "error"
            }
        }
    },
    # End node with output mappings
    {
        "id": "end",
        "type": "core.control.end",
        "typeVersion": "1.0",
        "display": {"label": "End"},
        "inputs": {},
        "outputs": {
            "matchedInvoiceNumber": {
                "source": "=js:$vars.buildOutputs.output.matchedInvoiceNumber"
            },
            "lineItemCount": {
                "source": "=js:$vars.buildOutputs.output.lineItemCount"
            }
        }
    }
]

flow['edges'] = [
    {
        "id": "edge-start-normalize",
        "sourceNodeId": "start",
        "sourcePort": "output",
        "targetNodeId": "normalizeInvoice",
        "targetPort": "input"
    },
    {
        "id": "edge-normalize-query",
        "sourceNodeId": "normalizeInvoice",
        "sourcePort": "success",
        "targetNodeId": "queryBillingdisputeerp1",
        "targetPort": "input"
    },
    {
        "id": "edge-query-build",
        "sourceNodeId": "queryBillingdisputeerp1",
        "sourcePort": "output",
        "targetNodeId": "buildOutputs",
        "targetPort": "input"
    },
    {
        "id": "edge-build-end",
        "sourceNodeId": "buildOutputs",
        "sourcePort": "success",
        "targetNodeId": "end",
        "targetPort": "input"
    }
]

# Definitions: keep existing trigger + connector defs, add script and end
existing_defs = {d['nodeType']: d for d in flow['definitions']}
# Add script def
existing_defs[script_def['nodeType']] = script_def
# Add end def
existing_defs[end_def['nodeType']] = end_def
flow['definitions'] = list(existing_defs.values())

# Variables
existing_nodes_vars = {v['id']: v for v in flow.get('variables', {}).get('nodes', [])}

# Add normalizeInvoice node vars
existing_nodes_vars['normalizeInvoice.output'] = {
    "id": "normalizeInvoice.output",
    "type": "object",
    "binding": {"nodeId": "normalizeInvoice", "outputId": "output"}
}
