existing_nodes_vars['buildOutputs.output'] = {
    "id": "buildOutputs.output",
    "type": "object",
    "binding": {"nodeId": "buildOutputs", "outputId": "output"}
}
existing_nodes_vars['buildOutputs.error'] = {
    "id": "buildOutputs.error",
    "type": "object",
    "binding": {"nodeId": "buildOutputs", "outputId": "error"}
}

flow['variables'] = {
    "globals": [
        {
            "id": "invoiceNumber",
            "direction": "in",
