# Layout: placeholder positions for new nodes
flow['layout'] = {
    "nodes": {
        "start": {"position": {"x": 100, "y": 144}, "size": {"width": 96, "height": 96}, "collapsed": False},
        "normalizeInvoice": {"position": {"x": 260, "y": 144}, "size": {"width": 96, "height": 96}, "collapsed": False},
